Translate("esES", "overlord-mok-morokk", {
	title = "Señor supremo Mok'Morokk",
	subtitle = "Señor supremo de los Quebrantarrocas",
	found = "Poblado Murohelecho",
	hint = [=[Inclínese ante el señor supremo de los Quebrantarrocas en el Poblado Murohelecho.]=],
	allegiance = "Ogros Quebrantarrocas · Horda",
	aliases = { "Mok'Morokk" },
	sections = {
		{
			title = "Resumen",
			text = [=[El señor supremo Mok'Morokk gobierna a los {red:stonemaul-ogres}ogros Quebrantarrocas{/red} desde el {link:brackenwall-village}Poblado Murohelecho{/link}. {link:rexxar}Rexxar{/link} lo nombró señor supremo, y Mok'Morokk nunca deja que nadie lo olvide. Cuando los dragones negros quemaron la aldea Quebrantarrocas del sur, condujo a su pueblo hacia el norte, a los juncos. Él lo llama sabiduría. Muchos de sus ogros lo llaman huir.]=],
		},
		{
			title = "Importancia",
			text = [=[Mok'Morokk muestra lo que el poder puede hacer a un líder al que nadie vigila. Era fuerte mientras {link:rexxar}Rexxar{/link} dirigía el clan. Cuando Rexxar se marchó, empezó a exigir servicio en lugar de prestarlo, y su pueblo empezó a volverse contra él.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Sacó a los Quebrantarrocas de su antigua aldea cuando llegaron los dragones negros.
• Envió a otros de vuelta a las ruinas a buscar el grog, el rapé y el cofre que había dejado atrás.
• Se negó a tomar las armas contra la progenie de {link:onyxia}Onyxia{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Las cosas del señor supremo",
			hint = "Recupere lo que el señor supremo dejó atrás en el sur.",
			text = [=[Mok'Morokk dejó su hogar con tanta prisa que olvidó las cosas que más quería. No volvió a por ellas él mismo. Estaba demasiado ocupado dirigiendo, dijo. Así que otros fueron al sur, al fuego de las {link:stonemaul-ruins}Ruinas Quebrantarrocas{/link} y del Cubil de la Llama, y le trajeron su grog, su rapé y su caja del tesoro.]=],
		},
		{
			title = "El desafío",
			hint = "Desafíe al señor supremo en su propia aldea.",
			text = [=[{link:draz-zilb}Draz'Zilb{/link} había decidido que el clan necesitaba un nuevo líder. Cuando el señor supremo fue desafiado en {link:brackenwall-village}Murohelecho{/link}, se rio y prometió una paliza. Perdió. El poderoso señor supremo de los Quebrantarrocas huyó de su propia aldea como un niño asustado, y los ogros empezaron a hablar de elegir a un líder que los llevara a casa.]=],
		},
	},
	mentions = {
		{ text = "Overlord Mok'Morokk's Concern" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "Challenge Overlord Mok'Morokk" },
	},
	bonds = {
		{ id = "rexxar", name = "Rexxar", note = "lo nombró señor supremo" },
		{ id = "draz-zilb", name = "Draz'Zilb", note = "tramó su caída" },
		{ id = "tharg", name = "Tharg", note = "lo culpa de la huida" },
	},
})

